    const liveDue = due(sumAmounts(live.map((c) => c.amount)), this.pctOf().get(p.grade));
    if (liveDue === null) return live.length === 0 && fixed.length > 0 ? sumAmounts(fixed) : null;
    return sumAmounts([...fixed, liveDue]);
  }'''
